34	const BASE_PREMIUMS: Record<string, number> = {
35	  sword: 100,
36	  amulet: 60,
37	  staff: 80,
38	  potion: 40,
39	  rune: 25,
40	  moonstone: 25,
41	};
42	
43	// Percentages are applied as integer arithmetic (× percent ÷ 100) rather than
44	// as a float rate (× 1.1): this keeps intermediate values integral and avoids
45	// binary floating-point error — 100 * 1.1 is 110.00000000000001, but
46	// (100 * 110) / 100 is exact. Premiums round up in MHPCO's favour at the end.
47	const ONE_HUNDRED_PERCENT = 100;
48	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
49	const ADMIN_FEE = 5;
50	
51	const applyPercent = (amount: number, percent: number): number =>
52	  (amount * percent) / ONE_HUNDRED_PERCENT;
53	
54	const addSurcharge = (amount: number, surchargePercent: number): number =>
55	  applyPercent(amount, ONE_HUNDRED_PERCENT + surchargePercent);
56	
57	const COMPONENT_TYPES = ["rune", "moonstone"];
58	const BUILDING_BLOCK_SIZE = 3;
59	const BUILDING_BLOCK_BASE_PREMIUM = 60;
60	const CURSED_SURCHARGE_PERCENT = 50;
61	
62	const isComponent = (item: Item): boolean => COMPONENT_TYPES.includes(item.type);
63	
64	const basePremiumOf = (item: Item): number => {
65	  const listed = BASE_PREMIUMS[item.type];
66	  return item.cursed ? addSurcharge(listed, CURSED_SURCHARGE_PERCENT) : listed;
67	};
68	
69	const sumBasePremiums = (items: Item[]): number =>
70	  items.reduce((total, item) => total + basePremiumOf(item), 0);
71	
72	// Alike components are grouped into building blocks of 3, which carry a
73	// special base premium; the remaining components are priced individually.
74	// Total over the empty group: no components means no blocks and no remainder.
75	const alikeComponentsBasePremium = (components: Item[]): number => {
76	  const blockCount = Math.floor(components.length / BUILDING_BLOCK_SIZE);
77	  const unblocked = components.slice(blockCount * BUILDING_BLOCK_SIZE);
78	  return blockCount * BUILDING_BLOCK_BASE_PREMIUM + sumBasePremiums(unblocked);
79	};
80	
81	const groupByType = (items: Item[]): Item[][] => [
82	  ...items
83	    .reduce(
84	      (groups, item) =>
85	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
86	      new Map<string, Item[]>(),
87	    )
88	    .values(),
89	];
90	
91	// Components and main items are priced by different rules, so each group is
92	// totalled separately: components by building block, main items item by item.
93	const componentsBasePremium = (components: Item[]): number =>
94	  groupByType(components).reduce(
95	    (total, alike) => total + alikeComponentsBasePremium(alike),
96	    0,
97	  );
98	
99	const totalBasePremium = (items: Item[]): number =>
100	  sumBasePremiums(items.filter((item) => !isComponent(item))) +
101	  componentsBasePremium(items.filter(isComponent));
102	
103	const quote = (step: QuoteStep): QuoteResult => {
104	  const basePremium = totalBasePremium(step.items);
105	  const premiumAfterFirstInsurance = addSurcharge(
106	    basePremium,
107	    FIRST_INSURANCE_SURCHARGE_PERCENT,
108	  );
109	  return { premium: Math.ceil(premiumAfterFirstInsurance) + ADMIN_FEE };
110	};
111	
112	export const runScenario = (scenario: Scenario): ScenarioResult => ({
113	  results: scenario.steps.map(quote),
114	});
