const isComponent = (item: Item): boolean => COMPONENT_TYPES.includes(item.type);

const listedPremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];

// Risk surcharges are per-item properties of the insured object, each raising
// that item's premium by a percentage. They stack multiplicatively: an item
// matching two rules is surcharged by the first, then by the second.
interface RiskSurcharge {
  appliesTo: (item: Item) => boolean;
  percent: number;
}

const RISK_SURCHARGES: RiskSurcharge[] = [
  { appliesTo: (item) => item.cursed === true, percent: 50 },
];

const riskAdjustedPremiumOf = (item: Item): number =>
  RISK_SURCHARGES.reduce(
    (premium, surcharge) =>
      surcharge.appliesTo(item) ? addSurcharge(premium, surcharge.percent) : premium,
    listedPremiumOf(item),
  );

const sumRiskAdjustedPremiums = (items: Item[]): number =>
  items.reduce((total, item) => total + riskAdjustedPremiumOf(item), 0);
